properties.query:
// Only events ingested since the last run (see tools/build.py)
let CowrieNew = Cowrie_CL | where ingestion_time() > ago(1h);
union
    (CowrieNew | where eventid =~ "cowrie.login.success" | extend event_type = "cowrie_login_success"),
    (CowrieNew | where (eventid =~ "cowrie.command.input" and input matches regex "\\b(wget|curl|tftp|ftpget|scp)\\b|/dev/tcp/|echo\\s+-[a-z]*e[a-z]*\\s+[\"']?(\\\\x[0-9a-fA-F]{2}){4}") or (eventid in~ ("cowrie.session.file_download", "cowrie.session.file_download.failed")) | extend event_type = "cowrie_tool_transfer")
| summarize event_type_count = dcount(event_type), src_ip = take_any(src_ip) by bin(TimeGenerated, 5m), session
| where event_type_count >= 2
// One alert per source IP
| summarize Matches = count(), FirstSeen = min(TimeGenerated), LastSeen = max(TimeGenerated) by src_ip
